insert into nexus.reviews (id, data) values
  ('rev_1', {"name":"Tanvir Ahmed (Sylhet)","rating":5,"product":"Free Fire 610 Diamonds","text":"Top-up received in literally 15 seconds after bKash payment! Fastest top-up service in Bangladesh.","avatar":"https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=100&q=80","verified":true,"status":"APPROVED","ts":1794484514171,"id":"rev_1"}::jsonb),
  ('rev_2', {"name":"Shahriar Hossain (Chittagong)","rating":5,"product":"USDT (TRC20) Cashout","text":"Exchanged $150 USDT to bKash. Exchange rate was 121.50 and money arrived in 3 minutes. Truly professional service.","avatar":"https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?w=100&q=80","verified":true,"status":"APPROVED","ts":1794473714171,"id":"rev_2"}::jsonb),
  ('rev_3', {"name":"Farhana Yasmin (Dhaka)","rating":5,"product":"Canva Pro Lifetime License","text":"Upgraded my own personal email in Canva Pro. All brand kits and premium stock images work perfectly!","avatar":"https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=100&q=80","verified":true,"status":"APPROVED","ts":1794448514171,"id":"rev_3"}::jsonb),
  ('rev_4', {"name":"Rakib Hassan (Rajshahi)","rating":5,"product":"PUBG Mobile 660 UC","text":"Direct Character ID instant top-up. Clean interface and instant wallet payment without delays.","avatar":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&q=80","verified":true,"status":"APPROVED","ts":1794405314171,"id":"rev_4"}::jsonb)
